/**
 * Agent extraction (M3, plan §4.3): `agentFromTf` turns an
 * `elementum_agent` block + its tool blocks (delegated to
 * `entities/agent-tool/from-tf.ts`) + its a2a-skill blocks (delegated to
 * `entities/agent-a2a-skill/from-tf.ts`, issue #68) into the normalized
 * shape `printAgentV2` consumes. Platform ids come only from the stream's
 * import blocks and stay data-side — they never reach printed source.
 */
import { type FromTfContext } from "../../engine/pull/context.js";
import { type TfBlock } from "../../engine/tf/index.js";
import { type NormalizedA2ASkill } from "../agent-a2a-skill/from-tf.js";
import { type NormalizedAgentTool } from "../agent-tool/from-tf.js";
import type { AgentAuthentication, AgentStartingAction } from "./build.js";
import type { AgentToolRunAs } from "./tools.js";
/**
 * A resolved skill reference: this app's own skill (by catalog key), a
 * foreign app's skill (by name + foreign app refName if the app is
 * recognized), or an unresolvable platform UUID literal.
 */
export type NormalizedSkillRef = {
    readonly kind: "self";
    readonly key: string;
} | {
    readonly kind: "foreign";
    readonly name: string;
    readonly appName: string;
    readonly appRefName?: string;
} | {
    readonly kind: "unresolved";
    readonly id: string;
};
export type NormalizedSkillAccess = {
    readonly mode: "NONE" | "ALL" | "ALL_APP";
    readonly preloadedSkills?: readonly NormalizedSkillRef[];
} | {
    readonly mode: "CUSTOM";
    readonly skills: readonly NormalizedSkillRef[];
    readonly preloadedSkills?: readonly NormalizedSkillRef[];
};
export interface NormalizedAgent {
    /** Authoring key = the bijective image of the exported label. */
    readonly refName: string;
    readonly name: string;
    readonly description: string;
    readonly type?: "elementum" | "bedrock";
    readonly bedrockAgentArn?: string;
    readonly instructions?: string;
    readonly firstMessage?: string;
    readonly maxLength?: number;
    /** org.ts `aiProviders.<provider>.models.<model>` compound key ("<provider>.<model>"), when pinned. */
    readonly connectorKey?: string;
    readonly skillAccess?: NormalizedSkillAccess;
    readonly runAs?: AgentToolRunAs;
    readonly agentAuthentication?: AgentAuthentication;
    readonly conversationIdleTimeout?: string;
    readonly a2aStreaming?: boolean;
    readonly a2aCreateRecordEnabled?: boolean;
    readonly startingActions?: readonly AgentStartingAction[];
    readonly tools: readonly NormalizedAgentTool[];
    readonly a2aSkills?: readonly NormalizedA2ASkill[];
}
export interface AgentFromTfResult {
    readonly agent?: NormalizedAgent;
    /** Set when the agent can't be authored on the terraform path (variant types) — reported, not fatal. */
    readonly skippedReason?: string;
}
/**
 * The `elementum_agent` block + its tool blocks + its a2a-skill blocks →
 * the normalized agent. Blocks belonging to OTHER agents are skipped with a
 * diagnostic (the caller partitions per-agent by agent_id, but stays
 * defensive).
 */
export declare function agentFromTf(agentBlock: TfBlock, toolBlocks: readonly TfBlock[], appLabel: string, _appRefName: string, ctx: FromTfContext, a2aSkillBlocks?: readonly TfBlock[]): AgentFromTfResult;
